{
  "propositions": [
    {
      "id": "P1",
      "proposition": "The replacement definition of “eligible student” establishes a disability-based route for Tennessee residents who meet the enrollment/history requirement and have autism, deaf-blindness, hearing impairments, intellectual disability, orthopedic impairments, traumatic brain injury, visual impairments, developmental delay, multiple disabilities, a specific learning disability, or deafness, as defined by the state board of education pursuant to § 49-10-102. The child must have an active IEP in accordance with 34 C.F.R. § 300 et seq., § 49-10-102, and state board regulations, identifying one of those disabilities as primary or secondary when the department receives the participation request.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "\"Eligible student\" means a resident of this state who:"
    },
    {
      "id": "P2",
      "proposition": "For the disability-based eligibility route, the student must have enrolled in and attended a Tennessee public school for the full school year immediately preceding the year of receiving an IEA, be enrolling in a Tennessee school for the first time, or have received an IEA in the previous school year.",
      "importance": "supporting",
      "section": "SECTION 1",
      "source_quote": "Meets at least one (1) of the following requirements:"
    },
    {
      "id": "P3",
      "proposition": "The replacement definition separately makes a Tennessee-resident child eligible if the child has a medical condition that inhibits in-person school attendance, as determined by the state board of education, and is entitled to attend a public school. This route does not require the disability, IEP, or enrollment/history conditions of the disability-based route.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "Is a child with a medical condition that inhibits the child from\n\n attending school in person, as determined by the state board of\n\n education;"
    },
    {
      "id": "P4",
      "proposition": "The replacement definition of “participating school” includes a nonpublic school meeting Part 14 requirements and seeking to enroll eligible students, and, for students eligible under the medical-condition route in § 49-10-1402(3)(B), a home school as defined in § 49-6-3050(a)(1).",
      "importance": "core",
      "section": "SECTION 2",
      "source_quote": "For an eligible student, as defined in subdivision (3)(B), a home\n\n school, as defined in § 49-6-3050(a)(1);"
    },
    {
      "id": "P5",
      "proposition": "New § 49-10-1404(d) makes § 49-10-1404 inapplicable to students eligible under the medical-condition route in § 49-10-1402(3)(B) and participating home schools defined in § 49-10-1402(6)(B).",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "This section does not apply to an eligible student"
    },
    {
      "id": "P6",
      "proposition": "The bill limits the participating-school references in § 49-10-1403(d) and § 49-10-1405(a)(7) to the nonpublic schools defined in § 49-10-1402(6)(A), by inserting that definitional cross-reference after “A participating school” and “of participating schools,” respectively.",
      "importance": "supporting",
      "section": "SECTIONS 4–5",
      "source_quote": "adding \", as defined in § 49-10-1402(6)(A),\" after \"A participating school\"."
    },
    {
      "id": "P7",
      "proposition": "A parent of a student eligible under the medical-condition route must ensure that IEA funds are used only for approved expenses listed in § 49-10-1403(b).",
      "importance": "core",
      "section": "SECTION 6(a)",
      "source_quote": "shall ensure\n\n that funds in an IEA are used only for approved expenses listed in § 49-10-1403(b)."
    },
    {
      "id": "P8",
      "proposition": "The department must create and implement a process for regular monitoring of IEA funds for students eligible under the medical-condition route to ensure compliance with the new section and § 49-10-1403(b).",
      "importance": "core",
      "section": "SECTION 6(b)",
      "source_quote": "The department shall create and implement a process"
    },
    {
      "id": "P9",
      "proposition": "The department may suspend or terminate an eligible student's program participation if it determines that the parent failed to comply with the requirements of the new section.",
      "importance": "core",
      "section": "SECTION 6(c)",
      "source_quote": "The department may suspend or terminate an eligible student from\n\n participating in the program"
    },
    {
      "id": "P10",
      "proposition": "A student whose participation is terminated under the new section's subsection (c) is ineligible to participate in the program in the future.",
      "importance": "core",
      "section": "SECTION 6(c)",
      "source_quote": "then the student is\n\n ineligible from participating in the program in the future."
    },
    {
      "id": "P11",
      "proposition": "The act takes effect July 1, 2026.",
      "importance": "supporting",
      "section": "SECTION 7",
      "source_quote": "This act takes effect July 1, 2026, the public welfare requiring it."
    }
  ]
}

